// Authored content for 3.2.9.1 Plant virus diseases (OxfordAQA 9610 v5.1, printed p.25; statements 3.2.9.1.s1–s3 in
// data/spec.js). Official wording: "Many important plant diseases are caused by viruses. They are responsible for losses in
// crop production and quality of produce in all parts of the world. Infected plants may show a range of symptoms
// depending on the disease. There may be yellowing of leaves, leaf distortion or abnormalities of other parts of the
// plant. As plants are immobile, transmission of viruses usually involves vectors such as aphids."
// Required: viruses cause important crop diseases worldwide (yield and quality); symptoms vary with the disease (yellowing,
// distortion, abnormalities of other parts); plants are immobile, so transmission usually involves vectors such as aphids.
// Supporting (labelled): named viruses and figures, other vectors and routes, transmission types, disease control and
// the Gulf examples. Every figure quoted is from a source listed at the foot of the notes (checked 11 November 2026);
// the field maps and control trial are HYPOTHETICAL (B.aphidData) and labelled so.
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.aphidArt, D = window.BIO.aphidData;
  const R = "3.2.9.1";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const P = (slot, o) => window.BIO.views.photo(slot, o);
  const f0 = (x) => (Math.round(x + 1e-9)).toFixed(0), f1 = (x) => (Math.round(x * 10 + 1e-9) / 10).toFixed(1);
  const tbl = (rows, head) => `<table class="tbl"><thead><tr>${head.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;

  // Real figures (see SOURCES)
  const OMAN = { fields: 320, perField: 100, samples: 716, lo1: 34.2, hi1: 78.1, lo2: 25.6, hi2: 75, viruses: 8, mixed: 46 };
  const BYDV_MAX_LOSS = 60; // % reduction in wheat grain yield, upper end (Jones 2021)
  // HYPOTHETICAL yield for a calculation using the BYDV upper figure
  const WHEAT = { healthy: 7.5 }; const wheatLow = (WHEAT.healthy * (100 - BYDV_MAX_LOSS)) / 100;
  // Field data (HYPOTHETICAL)
  const bA = (w) => D.bandPct("A", w), ringB = (w) => D.ringPct(w);
  const fieldTable = (f) => f === "A" ? tbl([2, 3, 4, 5, 6].map((w) => [String(w), ...bA(w).map(f1)]), ["Week", "Columns 1–3 / %", "Columns 4–6 / %", "Columns 7–9 / %", "Columns 10–12 / %"])
    : tbl([2, 3, 4, 5, 6].map((w) => [String(w), ...ringB(w).map((r) => f1(r.pct))]), ["Week", "Source plant and its 8 neighbours / %", "2 to 3 plants from the source / %", "4 or more plants from the source / %"]);
  const TR = D.TRIAL; const tr = (k) => D.trialRow(k); const red = (k) => D.pctReduction(k);
  const trialTable = tbl(TR.map((x) => [x.t, x.plots.join(", "), f1(x.mean), `${x.min} to ${x.max}`, String(x.yield)]), ["Treatment", "% plants with mosaic in each of 4 plots", "Mean / %", "Range / %", "Marketable yield / kg per plot (mean)"]);

  const SOURCES = `<details class="tiny muted"><summary>Sources (checked 11 November 2026)</summary><p>Jones R.A.C. (2021) Global plant virus disease pandemics and epidemics. <em>Plants</em> 10, 233 (<a href="https://doi.org/10.3390/plants10020233" target="_blank" rel="noopener">doi:10.3390/plants10020233</a>): economic impact estimated in 2014 at more than US$30 billion a year; 47 % of the pathogens causing emerging and re-emerging plant disease epidemics are viruses; yellow dwarf in wheat (leaf yellowing or reddening; grain yield reduced by up to 60 %; persistently aphid-transmitted); ZYMV seed-borne and spread between continents mainly in the cucurbit seed trade. Syller J. (2014) <em>Molecular Plant Pathology</em> 15, 417–426 (<a href="https://doi.org/10.1111/mpp.12101" target="_blank" rel="noopener">doi:10.1111/mpp.12101</a>): aphids spread 28 % of the nearly 700 vector-transmitted plant virus species; non-persistent, semi-persistent and persistent transmission. Persley D. and Gambley C. (2010) <em>Viruses in vegetable crops in Australia: integrated virus disease management</em>, Queensland Government (whiteflies and tomato yellow leaf curl virus; thrips and tomato spotted wilt virus; the dagger nematode and tobacco ringspot virus; seed and contact transmission of tomato mosaic virus; barrier crops, virus-free seed and transplants, reflective mulches, oil sprays, resistant varieties, timing). UMass Extension Vegetable Program (2018) <a href="https://www.umass.edu/agriculture-food-environment/vegetable/fact-sheets/cucumber-mosaic-virus" target="_blank" rel="noopener">Cucumber mosaic virus</a> (host range of more than 1,200 species; at least 75 aphid species; non-persistent; infected weeds at field borders the main source; insecticides not generally useful). Summers C.G., University of California, <a href="https://ucanr.edu/media/234819" target="_blank" rel="noopener">Aphids, viruses and watermelons</a> (non-persistent viruses acquired in test probes of 20 to 30 seconds; insecticides not effective against them). Gonsalves C., Lee D.R. and Gonsalves D. (2004) Transgenic virus-resistant papaya, <em>APSnet Features</em> (PRSV transmitted by aphids within seconds; resistant papaya released in Hawaii in 1998, half the bearing acreage by 2000). Ephytia, INRAE: Squash mosaic virus (spread mainly by beetles, and by seed and contact). Gulf region: Zouba A.A. et al. (1997) Survey of virus diseases of cucurbits in the Batinah region of the Sultanate of Oman, <em>Arab Journal of Plant Protection</em> 15, 43–46; Al-Saleh M.A. and Al-Shahwan I.M. (1997) Viruses infecting cucurbits in Riyadh, Gassim and Hail regions of Saudi Arabia, <em>Arab Gulf Journal of Scientific Research</em> 15, 223–254; Jones R.A.C. (2020) <em>Viruses</em> 12, 1388 (cacao swollen shoot virus spread by mealybugs). El Hamalawi Z.A. and Al Masoum A. (1999) Effect of reflective mulches and floating row covers on the spread of viral diseases and the production of squash in the United Arab Emirates, <em>Emirates Journal of Food and Agriculture</em> 11, 94–106 (<a href="https://doi.org/10.9755/ejfa.v11i1.4949" target="_blank" rel="noopener">doi:10.9755/ejfa.v11i1.4949</a>). Gulf figures are taken from the published abstracts.</p></details>`;

  // ---- Crop Disease Investigation (kind aphidCropInvestigation) ----
  const cdi = { kind: "aphidCropInvestigation", title: "Crop Disease Investigation",
    note: "Three parts: name the symptom in each photograph; compare how disease spread in two fields over six weeks; then (stretch) evaluate ways of controlling an aphid-borne virus. The photographs are real; the field maps and the trial results are HYPOTHETICAL data made up for this exercise, following patterns reported in the cited sources.",
    questions: [
      { part: 1, slot: "virus-bydv", id: `q-${R}-ic1`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Wheat infected with barley yellow dwarf virus. Which symptom is shown most clearly?", options: ["Yellowing of leaves", "Abnormal fruit", "Wilting caused by blocked xylem", "Holes eaten in the leaves"], answer: 0, explanation: "Several leaves have turned bright yellow beside healthy green ones: yellowing (chlorosis)." },
      { part: 1, slot: "virus-zymv", id: `q-${R}-ic2`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "A courgette (zucchini) leaf infected with zucchini yellow mosaic virus. Which description fits it best?", options: ["Mottled light and dark green, with a puckered, distorted blade", "Evenly yellow all over, but a normal shape", "Healthy colour and shape, with small holes", "Brown and dried out"], answer: 0, explanation: "The leaf shows a mosaic of light and dark green and its blade is puckered and misshapen: leaf distortion." },
      { part: 1, slot: "virus-cmv", id: `q-${R}-ic3`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Cucumbers from plants infected with cucumber mosaic virus. How does this symptom reduce the value of the crop?", options: ["Blotchy, bumpy fruit are of lower quality and may be unmarketable", "The fruit contain the virus, which is harmful to people who eat them", "The fruit are larger, so fewer fit in a box", "The symptoms only affect leaves, so value is unchanged"], answer: 0, explanation: "An abnormality of another part of the plant (the fruit) reduces quality of produce. Plant viruses do not infect people." },
      { part: 1, slot: "virus-prsv", id: `q-${R}-ic4`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "A papaya leaf infected with papaya ringspot virus. What is this pattern of light and dark patches called?", options: ["Mosaic", "Wilting", "Necrotic spotting caused by fungi", "Variegation inherited from the parent"], answer: 0, explanation: "A mosaic is an irregular pattern of light green or yellow and dark green areas; the distorted leaflets show leaf distortion as well." },
      { part: 2, id: `q-${R}-ic5`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Look at Field A (select Field A). Which conclusion is best supported by the maps?", options: ["The virus entered from the weedy margin and spread into the field", "The virus started in the centre of the field", "Infection was equally likely anywhere in the field", "The virus spread from the right-hand edge"], answer: 0, explanation: `Symptoms appear first in columns 1–3 (${f1(bA(2)[0])} % by week 2) and only later further in (${f1(bA(6)[3])} % of columns 10–12 by week 6): a gradient from the margin.` },
      { part: 2, id: `q-${R}-ic6`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: `Field B. By week 6, ${ringB(6)[0].pct === 100 ? "all the" : f0(ringB(6)[0].pct) + " % of"} plants within 1 plant of the first infected plant had symptoms, but only ${f1(ringB(6)[2].pct)} % of plants 4 or more plants away. What does this suggest?`, options: ["Most spread was from the first infected plant to nearby plants", "The virus came in from outside the field on the wind", "Plants far from the source were resistant", "The virus spread through the soil from the margin"], answer: 0, explanation: "Infection was clustered round one source plant (an infected transplant is one possibility), with a few longer jumps, as expected if aphids moving short distances do most of the spreading and winged aphids occasionally move further." },
      { part: 2, id: `q-${R}-ic7`, ref: R, stmts: S(1, 3), type: "short", marks: 3, stem: "Suggest one control measure that would suit Field A and one that would suit Field B. Explain each choice using the pattern of spread. (3 marks)", scheme: [{ point: "Field A: the source is outside the crop (weeds at the margin), so remove the weeds / plant a border or barrier crop / keep a gap between the margin and the crop", marks: 1 }, { point: "Field B: the source is inside the crop (one infected plant), so remove infected plants early (roguing) / use virus-free transplants", marks: 1 }, { point: "Explanation linking the measure to removing the source or stopping vectors reaching healthy plants", marks: 1 }], model: "In Field A, infection started next to the weedy margin, so the virus was probably brought in by aphids that had fed on infected weeds. Clearing the weeds or planting a barrier crop would reduce the number of virus-carrying aphids reaching the crop. In Field B, infection spread out from one plant inside the field, so removing that plant as soon as symptoms appeared (roguing) and using virus-free transplants would remove the source.", commonErrors: "Suggesting spraying antibiotics or antiviral drugs (there are none in practical use for crop viruses); not linking the measure to the pattern." },
      { part: 3, id: `q-${R}-ic8`, ref: R, stmts: S(1, 3), type: "mcq", marks: 1, stem: `In the trial, weekly insecticide reduced the mean percentage of plants with mosaic only from ${f1(tr("none").mean)} % to ${f1(tr("insect").mean)} %. Which explanation fits a non-persistent virus?`, options: ["Aphids pass on the virus in seconds when they probe, before the insecticide kills them", "Insecticides kill the virus inside the plant", "Aphids are not affected by insecticides", "Non-persistent viruses are spread only by seed"], answer: 0, explanation: "Non-persistent viruses are picked up and passed on in brief probes lasting seconds, often by winged aphids flying in from outside; the aphid has done the damage before a lethal dose acts." },
      { part: 3, id: `q-${R}-ic9`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: `Calculate the percentage reduction in the mean percentage of plants with mosaic for the floating row cover compared with the untreated plots (untreated mean ${f1(tr("none").mean)} %, row cover mean ${f1(tr("cover").mean)} %).`, options: [`${f0(red("cover"))} %`, `${f1(tr("none").mean - tr("cover").mean)} %`, `${f0((100 * tr("cover").mean) / tr("none").mean)} %`, `${f0((100 * (tr("none").mean - tr("cover").mean)) / tr("cover").mean)} %`], answer: 0, explanation: `(${f1(tr("none").mean)} − ${f1(tr("cover").mean)}) ÷ ${f1(tr("none").mean)} × 100 = ${f1(red("cover"))} %, about ${f0(red("cover"))} %. ${f1(tr("none").mean - tr("cover").mean)} is the difference in percentage points, not the percentage reduction.` },
      { part: 3, id: `q-${R}-ic10`, ref: R, stmts: S(1, 3), type: "short", marks: 4, stem: "Use the trial data to evaluate the use of a ZYMV-resistant variety and of reflective mulch to control aphid-borne mosaic viruses in squash. (4 marks)", scheme: [{ point: `Both reduced the mean % of plants with mosaic by about ${f0(red("mulch"))} % (from ${f1(tr("none").mean)} to ${f1(tr("mulch").mean)} %) and raised marketable yield (${tr("mulch").yield} and ${tr("resist").yield} kg against ${tr("none").yield} kg)`, marks: 1 }, { point: "The resistant variety still had mosaic in over a third of plants: it is resistant to ZYMV only, so other viruses (e.g. CMV, WMV) still infect it", marks: 1 }, { point: "Mulch repels / confuses incoming aphids so fewer land and probe; it works against several viruses but mainly while the plants are small, before the canopy covers it (Summers, University of California)", marks: 1 }, { point: "Limitation: hypothetical data / only 4 plots, ranges overlap (mulch 32 to 44, resistant 34 to 42) so the two are not clearly different; combining methods (integrated control) may work best", marks: 1 }], model: `Both treatments roughly halved the mean percentage of plants with mosaic, from ${f1(tr("none").mean)} % to ${f1(tr("mulch").mean)} % and ${f1(tr("resist").mean)} %, and both increased the marketable yield. The ZYMV-resistant variety still showed mosaic in more than a third of plants, probably because it is not resistant to the other aphid-borne viruses present. Reflective mulch reduces the number of aphids landing on the crop, so it works against several viruses, although it is most effective while the plants are small. The ranges overlap, there were only four plots, and the data are hypothetical, so we cannot say one is better; using them together could give more control.`, commonErrors: "Claiming the resistant variety is immune to all viruses; ignoring the overlapping ranges; forgetting to mention yield." },
    ] };

  window.BIO.content[R] = {
    status: "draft",
    keywords: ["plant virus", "plant viruses", "crop losses", "yield", "quality", "symptoms", "yellowing", "chlorosis", "mosaic", "mottle", "leaf distortion", "leaf curl", "stunting", "ringspot", "fruit", "vector", "vectors", "aphid", "aphids", "transmission", "whitefly", "thrips", "nematode", "seed transmission", "roguing", "resistant variety", "barley yellow dwarf virus", "BYDV", "zucchini yellow mosaic virus", "ZYMV", "cucumber mosaic virus", "CMV", "papaya ringspot virus", "PRSV", "non-persistent", "persistent", "reflective mulch", "row cover", "UAE", "Oman"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.2.9.1).</strong> That <strong>many important plant diseases are caused by viruses</strong>, causing <strong>losses in crop production and in the quality of produce</strong> worldwide; that infected plants show a <strong>range of symptoms depending on the disease</strong>, such as <strong>yellowing of leaves, leaf distortion</strong> or <strong>abnormalities of other parts</strong>; and that because <strong>plants are immobile</strong>, transmission of viruses <strong>usually involves vectors such as aphids</strong>. Named viruses, figures, other vectors and disease control are <span class="badge">supporting</span>: use them as examples, but you do not need to learn them. How aphids feed is in <a href="#/topic/3.2.9.2">3.2.9.2</a>.</div>

<h2 data-stmt="${R}.s1">1. Viruses as plant pathogens <span class="badge teal">required</span></h2>
<p>A <strong>virus</strong> is a non-cellular particle made of nucleic acid inside a protein coat. It can only reproduce <strong>inside a living host cell</strong>, using the cell's ribosomes, enzymes and ATP to make new virus particles (compare HIV in <a href="#/topic/3.2.4.2">3.2.4.2</a>, and pathogens in <a href="#/topic/3.2.1.1">3.2.1.1</a>). Plant viruses infect plant cells and spread through the plant, often in the <strong>phloem</strong>, so a whole plant can become infected from one point of entry.</p>
<p><strong>Many important plant diseases are caused by viruses.</strong> Viruses infect almost every kind of crop, from cereals such as wheat and barley to vegetables, fruit and root crops, in every part of the world.</p>
<p><span class="badge">supporting</span> A review by Jones (2021) gives two measures of their importance: virus disease epidemics were estimated in 2014 to cost <strong>more than US$30 billion a year</strong> worldwide, and <strong>47 %</strong> of the pathogens that cause emerging and re-emerging plant disease epidemics are viruses. Unlike many fungal diseases, which can be treated with fungicides, there are no chemicals that cure a virus-infected plant, so control depends on preventing infection.</p>

<h2 data-stmt="${R}.s1">2. Losses in yield and quality <span class="badge teal">required</span></h2>
<p>Viruses cause two kinds of loss, and exam answers should mention both:</p>
<ul><li><strong>Loss of crop production (yield).</strong> Infected plants grow less and produce less grain, fruit or tubers. Yellowed leaves contain less chlorophyll, so they absorb less light and the plant makes less sugar by photosynthesis for growth and for storage in the crop. Young plants infected early may die.</li>
<li><strong>Loss of quality of produce.</strong> Fruit can be blotchy, bumpy, misshapen or marked with rings, so it sells for less or cannot be sold at all, even if its mass is normal. Seed quality can be reduced too.</li></ul>
<table class="tbl"><thead><tr><th>Example (supporting)</th><th>Crop</th><th>What is lost</th></tr></thead><tbody>
<tr><td>Yellow dwarf (barley yellow dwarf virus and related viruses)</td><td>Wheat, barley, oats</td><td>Wheat grain yield reduced by up to ${BYDV_MAX_LOSS} % and seed quality impaired (Jones 2021)</td></tr>
<tr><td>Zucchini yellow mosaic virus (ZYMV)</td><td>Courgette, melon, cucumber and other cucurbits</td><td>A global epidemic in warm regions; spread between continents mainly in infected seed (Jones 2021)</td></tr>
<tr><td>Papaya ringspot virus (PRSV)</td><td>Papaya</td><td>Infected trees produce smaller and smaller fruit; young seedlings die. In Hawaii, a virus-resistant papaya was released to growers in 1998 and made up half the bearing acreage by 2000 (Gonsalves et al. 2004)</td></tr>
<tr><td>Cucumber mosaic virus (CMV)</td><td>More than 1,200 host species, including cucumber, melon and pepper</td><td>Small, distorted, discoloured fruit (UMass Extension 2018)</td></tr></tbody></table>
<p class="small"><span class="badge">supporting</span> <strong>Gulf crops.</strong> Surveys in Oman, Saudi Arabia and the UAE found aphid-borne viruses such as ZYMV, WMV and CMV in most cucurbit fields; in Oman a quarter to three quarters of plants had symptoms at harvest (Zouba et al. 1997). Reflective mulch and row covers reduced infection in a UAE trial (El Hamalawi and Al Masoum 1999).</p>

<h2 data-stmt="${R}.s2">3. Symptoms depend on the disease <span class="badge teal">required</span></h2>
<p>Infected plants may show a <strong>range of symptoms</strong>, and which ones appear depends on the virus, the kind of plant (and even its variety), how old the plant was when it was infected, and the growing conditions. The specification names three kinds:</p>
<ul><li><strong>Yellowing of leaves</strong> (chlorosis): the leaves lose chlorophyll. It may affect the whole leaf, or just the veins or patches.</li>
<li><strong>Leaf distortion</strong>: leaves are puckered, curled, crinkled, narrow or misshapen.</li>
<li><strong>Abnormalities of other parts of the plant</strong>: for example <strong>stunting</strong> (a smaller plant), and <strong>fruit</strong> that are mottled, bumpy, misshapen or marked with rings (ringspots).</li></ul>
<p>A very common pattern is a <strong>mosaic</strong> (or mottle): irregular patches of light green or yellow and dark green, which is why so many plant viruses have "mosaic" in their names.</p>
<p>Real photographs of four of these symptoms are in Part 1 of the investigation in section 6. A single virus rarely causes all of them.</p>
<p class="small"><span class="badge">supporting</span> <strong>Symptoms are clues, not proof.</strong> Nutrient deficiency, drought, herbicide damage and other pathogens can also cause yellowing or distortion, some infected plants show no symptoms, and one plant may carry several viruses. This is why surveys such as those above confirm infection with laboratory tests that detect virus proteins (ELISA, using antibodies) or nucleic acid.</p>

<h2 data-stmt="${R}.s3">4. Plants cannot move, so viruses need vectors <span class="badge teal">required</span></h2>
<p>An animal pathogen can be carried to a new host when an infected animal moves, coughs or touches another. <strong>Plants are immobile</strong>: an infected plant cannot move to a healthy one. A virus particle also cannot get through the waxy <strong>cuticle</strong> and the <strong>cellulose cell walls</strong> of an intact plant (<a href="#/topic/3.1.2.1">3.1.2.1</a>) by itself. So for most plant viruses, transmission depends on something that</p>
<ol><li><strong>picks up</strong> the virus from an infected plant,</li><li><strong>moves</strong> to a healthy plant, and</li><li><strong>puts the virus inside its living cells</strong>, through a wound.</li></ol>
<p>An organism that carries a pathogen from one host to another is a <strong>vector</strong>. The most important vectors of plant viruses are sap-sucking insects, especially <strong>aphids</strong>, whose mouthparts pierce plant cells and which fly from plant to plant (<a href="#/topic/3.2.9.2">3.2.9.2</a>). Each newly infected plant then becomes a <strong>source</strong> for further spread, as the cycle below shows.</p>

<h2 data-stmt="${R}.s3">5. Aphids and other routes <span class="badge teal">required</span></h2>
<p>The specification says transmission <strong>usually</strong> involves vectors <strong>such as</strong> aphids: aphids are the best-known example, but not the only one. <span class="badge">supporting</span> Aphids spread about <strong>28 %</strong> of the nearly 700 plant virus species known to be spread by vectors (Syller 2014). Other viruses are spread by whiteflies, thrips, soil nematodes or other insects, and some spread without a vector, in infected seed, tubers or cuttings, by grafting, or by contact (sap carried on hands and tools, or leaves rubbing together). Some viruses use more than one route: ZYMV is aphid-borne but has also spread between continents in infected seed.</p>
<p>The diagram shows the main routes. Do not write that all plant viruses are spread by aphids.</p>
<div class="notice small"><span class="badge">supporting</span> <strong>Aphids do not all carry viruses in the same way.</strong> <strong>Non-persistent</strong> viruses (for example CMV, ZYMV and PRSV) stick to the tips of the aphid's stylets during brief test probes lasting seconds, and are lost again within minutes to hours. <strong>Persistent</strong> viruses (for example barley yellow dwarf virus) are taken up from the phloem during long feeds, pass through the aphid's gut into its body and salivary glands, and are then injected with saliva for the rest of the aphid's life. There are intermediate (semi-persistent) types too. The type matters for control, as the investigation shows. Details are in <a href="#/topic/3.2.9.2">3.2.9.2</a>.</div>

<h2 data-stmt="${R}.s1 ${R}.s3">6. Investigating and controlling a virus disease <span class="badge">supporting</span></h2>
<p>Because infected plants cannot be cured, growers try to <strong>stop the virus reaching healthy plants</strong>: remove its sources, keep vectors off the crop, or grow plants it cannot infect. Every method is a way of breaking the cycle in section 4.</p>
<table class="tbl"><thead><tr><th>Method</th><th>How it breaks the cycle</th><th>Limits</th></tr></thead><tbody>
<tr><td>Virus-free seed, transplants or tubers</td><td>No source inside the crop at the start</td><td>Does not stop virus arriving from outside</td></tr>
<tr><td>Removing infected plants (roguing) and infected weeds</td><td>Removes sources</td><td>Plants can spread virus before symptoms show; does not stop aphids arriving already carrying virus</td></tr>
<tr><td>Resistant varieties</td><td>The virus cannot infect or multiply in them</td><td>Usually resistant to one virus only; resistance can break down</td></tr>
<tr><td>Insecticides</td><td>Kill aphids</td><td>Can reduce the spread of persistent viruses, which need long feeds; little effect on non-persistent viruses, which are passed on within seconds; can make aphids more restless</td></tr>
<tr><td>Mineral oil sprays, reflective mulch, row covers, barrier crops</td><td>Fewer aphids land, probe or carry virus to the crop</td><td>Mulch works mainly while plants are small; covers must come off when flowers need insect pollination</td></tr>
<tr><td>Timing of planting and separating crops</td><td>Young plants avoid the peak flights of winged aphids</td><td>Depends on local aphid flights</td></tr></tbody></table>
<p>Work through the investigation to apply these ideas to symptoms, maps and trial data.</p>

<h2 data-stmt="${R}.s1 ${R}.s2 ${R}.s3">7. Common misconceptions <span class="badge teal">required</span></h2>
<ul><li><strong>"Viruses only reduce the amount of crop."</strong> They also reduce its <strong>quality</strong>: blemished or misshapen produce may be unsaleable.</li>
<li><strong>"Each virus always causes the same symptoms."</strong> Symptoms depend on the virus, the host plant and its variety, its age and the conditions. Some infections show no symptoms.</li>
<li><strong>"Yellow leaves mean a virus."</strong> Nutrient shortage, drought and other diseases cause yellowing too; tests are needed to be sure.</li>
<li><strong>"All plant viruses are spread by aphids."</strong> Many are, but others are spread by whiteflies, thrips, nematodes, seed, grafting or contact.</li>
<li><strong>"The virus moves from plant to plant through the air."</strong> Plant viruses do not fly; they are carried by vectors (or in seed, sap and so on).</li>
<li><strong>"Spraying insecticide stops aphid-borne viruses."</strong> It often fails for non-persistent viruses, which are passed on within seconds before the aphid dies.</li>
<li><strong>"Plant viruses can be treated with antibiotics."</strong> Antibiotics act on bacteria, not viruses, and there is no practical cure for an infected plant.</li>
<li><strong>"Eating virus-infected fruit gives you the virus."</strong> Plant viruses do not infect people; the problem is loss of yield and quality.</li></ul>
<p class="small"><strong>Writing about vectors.</strong> A full answer links the two ideas: <em>plants cannot move</em>, so the virus must be <em>carried</em> by a vector such as an aphid, which <em>pierces</em> the plant cells and so puts the virus inside them.</p>
${SOURCES}`,
    diagrams: [
      { id: `d-${R}-2`, title: "Why plant viruses depend on vectors", status: "draft", svg: A.cycle(), caption: "Plants cannot move, so a vector does the moving. An infected plant is a source; an aphid picks up virus as it probes or feeds; it moves (winged females fly further); it passes the virus into the cells of a healthy plant, which becomes a new source.", alt: "A cycle of four boxes joined by arrows: 1 infected plant, a source; 2 aphid probes or feeds and picks up virus; 3 aphid moves, winged females fly further; 4 virus enters a healthy plant through the aphid's stylets. The centre says the newly infected plant becomes a source." },
      { id: `d-${R}-3`, title: "Routes by which plant viruses spread", status: "draft", svg: A.routes(), caption: "Aphids are one of several routes. Supporting examples: aphids (CMV, ZYMV, PRSV, WMV, BYDV), whiteflies (tomato yellow leaf curl virus), thrips (tomato spotted wilt virus), soil nematodes (tobacco ringspot virus), other insects such as mealybugs (cacao swollen shoot virus), infected seed (ZYMV, lettuce mosaic virus), infected tubers or cuttings (potato virus Y), grafting, and contact (tomato mosaic virus). Named viruses are supporting examples, not requirements. Sources: Syller (2014); Persley and Gambley (2010); Jones (2020, 2021).", alt: "A central circle labelled plant virus, must get into the cells of a new plant, joined by lines to nine boxes. At the top: aphids, about 28 percent of vector-borne viruses. On the left, other vectors: whiteflies, thrips, nematodes in soil, and other insect vectors such as mealybugs. On the right, routes with no vector: infected seed, infected tubers or cuttings, grafting, and contact by hands, tools and plants rubbing. Each box gives an example virus." },
    ],
    interactives: [cdi],
    focus: [
      { slot: "virus-bydv", title: "Yellow wheat: barley yellow dwarf", ref: R, explanation: () => `<p>Barley yellow dwarf virus infects wheat, barley and oats. It lives only in the <strong>phloem</strong>, and infected plants are often <strong>stunted</strong> with leaves that turn <strong>yellow</strong> (or red in some cereals), like the leaves in this photograph beside healthy green ones. It is spread by aphids in the <strong>persistent</strong> way: the aphid must feed on the phloem of an infected plant for some time to pick it up, and then stays infective for life. In wheat, yellow dwarf can reduce grain yield by up to ${BYDV_MAX_LOSS} % and damage seed quality (Jones 2021).</p>`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: "Barley yellow dwarf virus causes yellowing of wheat leaves. Explain how this symptom could reduce the yield of grain. (3 marks)", scheme: [{ point: "Yellow leaves have less chlorophyll", marks: 1 }, { point: "So less light is absorbed / less photosynthesis", marks: 1 }, { point: "So less sugar (sucrose) is made and translocated to the grain / less starch stored in the grain / less growth", marks: 1 }], model: "Yellowing means the leaves have lost chlorophyll, so they absorb less light and the rate of photosynthesis falls. Less sugar is made and translocated in the phloem to the developing grain, so less starch is stored and the yield of grain is lower.", commonErrors: "Saying the virus 'eats' the grain; leaving out the link through photosynthesis." } },
      { slot: "virus-zymv", title: "A distorted courgette leaf", ref: R, explanation: () => `<p>This courgette (zucchini) leaf has two symptoms of zucchini yellow mosaic virus: a <strong>mosaic</strong> of light and dark green and a puckered, <strong>distorted</strong> blade with ragged lobes. Fruit from infected plants can also be mottled and misshapen. ZYMV is spread by aphids in the <strong>non-persistent</strong> way and is also carried in seed, which helped it spread between continents in the international seed trade (Jones 2021). It is one of the viruses reported in cucurbit crops in Oman, Saudi Arabia and the UAE.</p>`,
        question: { id: `q-${R}-fx2`, ref: R, stmts: S(3), type: "short", marks: 2, stem: "ZYMV is carried both by aphids and in seed. Explain how each route lets the virus reach new plants even though plants cannot move. (2 marks)", scheme: [{ point: "Aphids pick up the virus from an infected plant and carry it (by walking or flying) to healthy plants, putting it into their cells when they probe", marks: 1 }, { point: "Infected seed carries the virus to wherever the seed is sown (even another country), so the seedling is infected from the start / becomes a source", marks: 1 }], model: "An aphid that probes an infected plant picks up virus on its stylets and carries it to a healthy plant, where its next probe puts the virus into the cells. Infected seed takes the virus wherever it is sown, so the new seedling is infected from the start and becomes a source of virus in the new crop.", commonErrors: "Saying the virus moves through the soil or the air by itself." } },
      { slot: "virus-cmv", title: "Mosaic on cucumber fruit", ref: R, explanation: () => `<p>Cucumber mosaic virus has one of the widest host ranges known, more than 1,200 plant species, and at least 75 species of aphid can spread it (UMass Extension 2018). These cucumbers show its effect on <strong>another part of the plant</strong>: the fruit skin is pale and blotchy with bumpy patches. Fruit like these may be perfectly edible, but they are of lower <strong>quality</strong> and are hard to sell. Infected weeds at the edges of fields are a main source of the virus, which is one reason why infection often starts at field margins.</p>`,
        question: { id: `q-${R}-fx3`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Cucumbers like these have a normal mass but a blotchy, bumpy skin. Which loss does this show?", options: ["Loss of quality of produce", "Loss of yield only", "No loss, because the mass is normal", "Loss caused by a bacterium"], answer: 0, explanation: "The specification names both losses: production (yield) and quality of produce. Blemished fruit sell for less or not at all." } },
      { slot: "virus-prsv", title: "Papaya ringspot: a resistant variety", ref: R, explanation: () => `<p>This papaya leaf shows the yellow and green <strong>mosaic</strong> and distorted leaflets caused by papaya ringspot virus; fruit develop ring-shaped spots. Aphids pass the virus on within seconds of feeding (Gonsalves et al. 2004), so insecticides cannot stop it. In Hawaii the virus devastated papaya growing in the 1990s; a <strong>virus-resistant</strong> papaya was released to growers in 1998 and by 2000 made up half of the bearing papaya area. A resistant variety works because the virus cannot multiply in it, whatever the aphids do.</p>`,
        question: { id: `q-${R}-fx4`, ref: R, stmts: S(1, 3), type: "short", marks: 2, stem: "Explain why planting a resistant variety controlled papaya ringspot virus when spraying insecticide could not. (2 marks)", scheme: [{ point: "Aphids pass the virus on within seconds of probing, before an insecticide can kill them", marks: 1 }, { point: "The resistant plants cannot be infected even when an aphid carrying the virus probes them / the virus cannot multiply in them, so no new sources form", marks: 1 }], model: "Aphids pass on papaya ringspot virus within seconds of probing a plant, so they infect it before any insecticide can kill them. A resistant variety cannot be infected even when an infective aphid probes it, so the crop stays healthy and does not become a source.", commonErrors: "Saying resistant plants kill aphids." } },
    ],
    examFocus: `<ul>
<li><strong>Two kinds of loss.</strong> Say <em>yield</em> (less grain, fruit or tubers) <em>and</em> <em>quality</em> (blemished, misshapen produce). Link yellowing to less chlorophyll, less photosynthesis and less growth.</li>
<li><strong>Symptoms vary with the disease.</strong> Yellowing, leaf distortion and abnormalities of other parts (stunting, mosaics, abnormal fruit). If shown a photograph, describe what you see, using these terms.</li>
<li><strong>Immobile, so vectors.</strong> Plants cannot move to each other, and a virus cannot cross an intact cell wall, so a vector such as an aphid carries it and puts it into the cells. Write "usually" and "such as": not every virus is aphid-borne.</li>
<li><strong>Data on spread.</strong> Infection that starts at one edge and moves inwards suggests a source outside the field; a cluster round one plant suggests a source inside. Calculate percentages and percentage change; compare means and comment on ranges and repeats.</li>
<li><strong>Evaluating control.</strong> Match the method to the source (inside or outside the crop) and to the type of transmission. Insecticides are a weak answer for non-persistent viruses; resistance is usually to one virus only.</li>
<li><strong>Common mistakes.</strong> Saying viruses are killed by antibiotics; saying all viruses are aphid-borne; saying viruses "fly" or "spread in the air" by themselves.</li></ul>`,
    synoptic: [
      { ref: "3.2.9.2", text: "How aphids feed on phloem sap with stylets, and how winged females spread viruses to new host plants." },
      { ref: "3.2.1.1", text: "Pathogens include viruses; how pathogens cause disease." },
      { ref: "3.2.4.2", text: "A virus replicates only inside host cells, using the host's ribosomes and enzymes (HIV)." },
      { ref: "3.2.8.2", text: "Many plant viruses move through the plant in the phloem, carried by mass flow." },
      { ref: "3.1.2.1", text: "The cellulose cell wall and cuticle are barriers a virus cannot cross unaided." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Plant virus diseases reduce", options: ["both crop yield and the quality of produce", "crop yield only", "quality of produce only", "the mass of soil available to crops"], answer: 0, explanation: "The specification names losses in crop production and in quality of produce." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which list contains only symptoms named in the specification for plant virus diseases?", options: ["Yellowing of leaves, leaf distortion, abnormalities of other parts", "Yellowing of leaves, fever, wilting", "Leaf distortion, coughing, root nodules", "Mosaic, swollen lymph nodes, stunting"], answer: 0, explanation: "Fever, coughing and lymph nodes belong to animals; root nodules are a normal feature of legumes." },
      { id: `q-${R}-qc3`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: "Complete the sentence.", text: "Plants are {{1}}, so transmission of viruses usually involves {{2}} such as aphids.", answers: { 1: ["immobile", "unable to move", "stationary", "fixed"], 2: ["vectors", "vector", "insect vectors"] }, explanation: "Immobile; vectors." },
      { id: `q-${R}-qc4`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Which statement about the spread of plant viruses is correct?", options: ["Many are spread by aphids, but others are spread by other vectors, seed or contact", "All plant viruses are spread by aphids", "Plant viruses travel through the air without a vector", "Plant viruses spread only through the roots"], answer: 0, explanation: "Aphids are the best-known vectors, but whiteflies, thrips, nematodes, seed, grafting and contact spread other viruses." },
      { id: `q-${R}-qc5`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why may two plants infected with the same virus show different symptoms?", options: ["Symptoms depend on the plant (and its variety), its age and the conditions as well as the virus", "One of the plants must also have a bacterial infection", "The virus has stopped reproducing in one plant", "Symptoms are decided only by the vector"], answer: 0, explanation: "The specification says symptoms depend on the disease; host, age and conditions all change them." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "What does the specification say about the importance of plant viruses?", back: "Many important plant diseases are caused by viruses; they cause losses in crop production and quality of produce in all parts of the world." },
      { id: `f-${R}-2`, front: "Two kinds of loss caused by plant viruses.", back: "Loss of yield (less grain, fruit or tubers) and loss of quality (blemished, misshapen produce that sells for less)." },
      { id: `f-${R}-3`, front: "How can yellowing reduce yield?", back: "Less chlorophyll, so less light absorbed and less photosynthesis: less sugar for growth and storage in the crop." },
      { id: `f-${R}-4`, front: "Why is there no 'cure' for a virus-infected crop?", back: "No practical chemical cures an infected plant (antibiotics do not act on viruses), so control means preventing infection." },
      { id: `f-${R}-5`, front: "Three kinds of symptom named in the specification.", back: "Yellowing of leaves; leaf distortion; abnormalities of other parts of the plant." },
      { id: `f-${R}-6`, front: "What is a mosaic symptom?", back: "Irregular patches of light green or yellow and dark green on a leaf (or fruit)." },
      { id: `f-${R}-7`, front: "Give two abnormalities of parts other than leaves.", back: "Stunting (smaller plant); abnormal fruit (blotchy, bumpy, misshapen, ringspots)." },
      { id: `f-${R}-8`, front: "What decides which symptoms appear?", back: "The disease (the virus), the kind and variety of plant, its age when infected and the growing conditions." },
      { id: `f-${R}-9`, front: "Why are symptoms alone not proof of a virus?", back: "Nutrient deficiency, drought and other pathogens cause similar symptoms; some infections are symptomless. Laboratory tests (e.g. ELISA) confirm." },
      { id: `f-${R}-10`, front: "Why do plant viruses usually need vectors?", back: "Plants are immobile, and a virus cannot cross an intact cuticle and cell wall, so something must carry it to a healthy plant and put it into the cells." },
      { id: `f-${R}-11`, front: "Define a vector (of a pathogen).", back: "An organism that carries a pathogen from one host to another." },
      { id: `f-${R}-12`, front: "Name the vector given in the specification.", back: "Aphids (\"vectors such as aphids\")." },
      { id: `f-${R}-13`, front: "Give three routes, other than aphids, by which plant viruses spread (supporting).", back: "Any three: whiteflies, thrips, soil nematodes, infected seed, infected tubers or cuttings, grafting, contact (hands, tools, rubbing leaves)." },
      { id: `f-${R}-14`, front: "Which vector spreads tomato yellow leaf curl virus (supporting)?", back: "Whiteflies, not aphids." },
      { id: `f-${R}-15`, front: "Roughly what share of vector-borne plant viruses do aphids spread (supporting)?", back: "About 28 % of the nearly 700 vector-transmitted species (Syller 2014)." },
      { id: `f-${R}-16`, front: "Non-persistent v persistent transmission in one line each (supporting).", back: "Non-persistent: on the stylet tips, picked up and passed on in seconds, soon lost. Persistent: taken up from phloem in long feeds, crosses the gut to the salivary glands, aphid infective for life." },
      { id: `f-${R}-17`, front: "Why do insecticides often fail against non-persistent viruses (supporting)?", back: "The aphid passes on the virus during a probe lasting seconds, before the insecticide kills it." },
      { id: `f-${R}-18`, front: "Infection starts at a field edge and moves inwards. What does it suggest?", back: "A source outside the field (e.g. infected weeds or an older crop) from which aphids carry virus in." },
      { id: `f-${R}-19`, front: "Four ways to control an aphid-borne virus (supporting).", back: "Any four: virus-free planting material; removing infected plants and weeds; resistant varieties; reflective mulch, oil sprays, row covers or barrier crops; timing of planting; insecticide (persistent viruses)." },
      { id: `f-${R}-20`, front: "A Gulf example of plant virus disease (supporting).", back: "Cucurbit viruses such as ZYMV, WMV and CMV in Oman, Saudi Arabia and the UAE; in Oman, average incidence at harvest was about 26 to 78 % of plants depending on crop and season (Zouba et al. 1997)." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which statement best explains why plant viruses are important in agriculture?", options: ["They cause many important crop diseases, reducing yield and quality worldwide", "They are the only pathogens of crop plants", "They only affect crops in tropical countries", "They improve crop yields by killing pests"], answer: 0, explanation: "Viruses cause losses in crop production and quality in all parts of the world; bacteria and fungi cause other crop diseases." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "A farmer's melons are the normal size but have pale, bumpy patches on the skin and sell for half the usual price. This is an example of", options: ["loss of quality of produce", "loss of yield", "a symptom caused only by aphid feeding damage", "a disease with no economic effect"], answer: 0, explanation: "The mass is normal, so the loss is in quality." },
      { id: `q-${R}-m3`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: `HYPOTHETICAL. A wheat crop would yield ${f1(WHEAT.healthy)} tonnes per hectare if healthy. Yellow dwarf can reduce wheat grain yield by up to ${BYDV_MAX_LOSS} % (Jones 2021). What is the lowest yield expected if the crop suffered this maximum loss?`, options: [`${f1(wheatLow)} t ha⁻¹`, `${f1((WHEAT.healthy * BYDV_MAX_LOSS) / 100)} t ha⁻¹`, `${f1(WHEAT.healthy - BYDV_MAX_LOSS / 100)} t ha⁻¹`, `${f1(WHEAT.healthy * 0.94)} t ha⁻¹`], answer: 0, explanation: `${f1(WHEAT.healthy)} × (100 − ${BYDV_MAX_LOSS}) ÷ 100 = ${f1(wheatLow)} t ha⁻¹. ${f1((WHEAT.healthy * BYDV_MAX_LOSS) / 100)} t ha⁻¹ is the amount lost, not the amount left.` },
      { id: `q-${R}-m4`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "A leaf has irregular patches of pale yellow and dark green. Which term describes this symptom?", options: ["Mosaic", "Wilting", "Stunting", "Galls"], answer: 0, explanation: "A mosaic (or mottle) is a patchwork of light and dark areas." },
      { id: `q-${R}-m5`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which observation is an abnormality of a part of the plant other than the leaves?", options: ["Small, misshapen fruit with ring-shaped marks", "Yellow veins on the leaves", "Curled, crinkled leaves", "Pale green patches on the leaves"], answer: 0, explanation: "The other three are all leaf symptoms (yellowing and distortion)." },
      { id: `q-${R}-m6`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "A grower sees yellowing leaves in a pepper crop. Why should she test the plants before concluding that a virus is the cause?", options: ["Other causes, such as nutrient deficiency, also cause yellowing", "Viruses never cause yellowing", "Yellowing always means a fungal infection", "Viruses cause symptoms only in fruit"], answer: 0, explanation: "Symptoms are clues; a laboratory test (for example ELISA) confirms which virus, if any, is present." },
      { id: `q-${R}-m7`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Why does transmission of plant viruses usually involve a vector?", options: ["Plants are immobile and a virus cannot get through an intact cell wall by itself", "Plant viruses are too large to infect plant cells directly", "Vectors make the virus less harmful", "Plants have no phloem for viruses to travel in"], answer: 0, explanation: "A vector carries the virus between immobile plants and puts it into living cells through a wound it makes." },
      { id: `q-${R}-m8`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Which virus is spread by whiteflies, not by aphids? (supporting)", options: ["Tomato yellow leaf curl virus", "Cucumber mosaic virus", "Zucchini yellow mosaic virus", "Barley yellow dwarf virus"], answer: 0, explanation: "The other three are aphid-borne." },
      { id: `q-${R}-m9`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Which statement about how aphids carry viruses is correct? (supporting)", options: ["Different viruses are carried in different ways, for example on the stylet tips or through the aphid's body", "Every aphid-borne virus is carried in the aphid's gut for life", "Aphids carry viruses only on their wings", "Aphids pass viruses to plants only through their droppings"], answer: 0, explanation: "Non-persistent viruses are held on the stylets and soon lost; persistent viruses circulate through the body and the aphid stays infective for life." },
      { id: `q-${R}-m10`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "In a squash field, symptoms appear first in the rows next to a strip of weeds and spread across the field over several weeks. What is the most likely explanation?", options: ["Aphids carried virus from infected weeds into the edge of the crop and then further in", "The virus spread from the centre of the field towards the edge", "The rows near the weeds were planted with resistant seed", "The virus was carried through the soil by the roots"], answer: 0, explanation: "A gradient from one edge points to a source outside the field on that side; infected weeds at field borders are a main source of CMV, for example." },
      // ---- gap fills ----
      { id: `q-${R}-g1`, ref: R, stmts: S(2), type: "gap", marks: 3, stem: "Complete the passage.", text: "Plants infected with viruses may show {{1}} of the leaves, leaf {{2}}, or abnormalities of other parts such as the {{3}}.", answers: { 1: ["yellowing", "chlorosis"], 2: ["distortion", "curling", "curl", "deformation", "puckering", "crinkling"], 3: ["fruit", "fruits", "flowers", "flower", "stem", "stems", "roots", "tubers", "seeds"] }, explanation: "Yellowing; distortion; fruit (or another named part)." },
      { id: `q-${R}-g2`, ref: R, stmts: S(1, 3), type: "gap", marks: 3, stem: "Complete the passage.", text: "Plant viruses cause losses in crop {{1}} and in the {{2}} of produce. Because plants cannot move, most plant viruses are carried from plant to plant by {{3}}.", answers: { 1: ["production", "yield", "yields"], 2: ["quality"], 3: ["vectors", "vector", "aphids", "insects", "insect vectors"] }, explanation: "Production (yield); quality; vectors (such as aphids)." },
      // ---- matching, sequencing, labelling ----
      { id: `q-${R}-mt1`, ref: R, stmts: S(2), type: "match", marks: 4, stem: "Match each symptom to its description.", pairs: [{ left: "Yellowing", right: "Loss of green colour from all or part of a leaf" }, { left: "Mosaic", right: "Irregular light and dark green patches" }, { left: "Leaf distortion", right: "Puckered, curled or misshapen leaves" }, { left: "Stunting", right: "The whole plant is smaller than normal" }] },
      { id: `q-${R}-mt2`, ref: R, stmts: S(3), type: "match", marks: 4, stem: "Match each virus to the way it is spread (supporting).", pairs: [{ left: "Cucumber mosaic virus", right: "Aphids, in brief probes" }, { left: "Tomato yellow leaf curl virus", right: "Whiteflies" }, { left: "Tomato spotted wilt virus", right: "Thrips" }, { left: "Tobacco ringspot virus", right: "Dagger nematodes in the soil" }] },
      { id: `q-${R}-sq1`, ref: R, stmts: S(3), type: "sequence", marks: 3, stem: "Put these events in order to show how an aphid spreads a virus to a healthy plant.", steps: ["The virus multiplies in the cells of an infected plant", "An aphid probes or feeds on the infected plant and picks up virus", "The aphid moves (for example a winged female flies) to a healthy plant", "The aphid's stylets pierce the healthy plant's cells, putting the virus inside", "The virus multiplies and the new plant becomes a source"], explanation: "Source, acquisition, movement, inoculation, new source." },
      { id: `q-${R}-lb1`, ref: R, stmts: S(2), type: "label", marks: 5, drag: true, stem: "The diagram compares a healthy plant with a plant infected by a virus. Name each numbered symptom.", svg: A.symptoms({ numbers: { "Stunting": 1, "Leaf distortion": 2, "Mosaic": 3, "Yellowing of leaves": 4, "Abnormal fruit": 5 } }), labels: [{ n: 1, answer: "Stunting" }, { n: 2, answer: "Leaf distortion" }, { n: 3, answer: "Mosaic" }, { n: 4, answer: "Yellowing of leaves" }, { n: 5, answer: "Abnormal fruit" }], bank: ["Stunting", "Leaf distortion", "Mosaic", "Yellowing of leaves", "Abnormal fruit", "Wilting", "Root rot"], explanation: "1 the plant is shorter than the healthy one; 2 puckered, misshapen leaves; 3 light and dark patches; 4 yellow leaf; 5 small fruit with pale blotches and rings." },
      // ---- data and short answer ----
      { id: `q-${R}-d1`, ref: R, stmts: S(1, 2), type: "short", marks: 4, stem: `Data (published survey, Zouba et al. 1997). Researchers surveyed ${OMAN.fields} cucurbit fields in Oman. In each field they examined ${OMAN.perField} plants and recorded how many had virus symptoms. Average incidence at harvest ranged from ${OMAN.lo1} to ${OMAN.hi1} in 1994/95 and from ${OMAN.lo2} to ${OMAN.hi2} in 1995/96, depending on the crop. They also tested ${OMAN.samples} samples from plants with symptoms in the laboratory (ELISA) and found ${OMAN.viruses} different viruses; ${OMAN.mixed} samples contained more than one virus.<br>(a) Use the data to explain why plant viruses are an important cause of crop losses in this region. (1 mark) (b) Suggest two reasons why incidence judged from symptoms might not equal the true percentage of plants infected. (2 marks) (c) Explain why the researchers tested samples in the laboratory as well. (1 mark)`, scheme: [{ point: "(a) Up to about three quarters of plants (78.1 / 75) had symptoms at harvest, so yield and/or quality of a large part of the crop would be reduced", marks: 1 }, { point: "(b) Some infected plants show no symptoms (yet), so incidence could be underestimated", marks: 1 }, { point: "(b) Other causes (nutrient deficiency, other pathogens, pests, herbicide) cause similar symptoms, so incidence could be overestimated", marks: 1 }, { point: "(c) To identify which virus(es) were present / confirm infection / detect mixed infections, because symptoms depend on the disease and do not identify the virus", marks: 1 }], model: "(a) In some crops about three quarters of the plants had symptoms by harvest, so a large share of the crop would have lower yield or quality. (b) Some infected plants may not show symptoms, so infection would be missed; and other problems such as nutrient deficiency or other pathogens cause similar yellowing or distortion, so some plants would be counted wrongly. (c) Symptoms do not tell you which virus is present, and some plants had more than one; ELISA identifies the viruses.", commonErrors: "Treating incidence from symptoms as exact; saying symptoms identify the virus." },
      { id: `q-${R}-d2`, ref: R, stmts: S(3), type: "short", marks: 4, stem: `HYPOTHETICAL data. The tables show the percentage of plants with symptoms in two squash fields over six weeks.<br><strong>Field A</strong> (weedy margin beside column 1)${fieldTable("A")}<strong>Field B</strong> (no weedy margin; one plant had symptoms in week 1)${fieldTable("B")}(a) Describe the pattern of spread in Field A. (1 mark) (b) Calculate how many times greater the percentage was next to the source than 4 or more plants away in Field B at week 6. Give your answer to 2 significant figures. (1 mark) (c) Explain how the two patterns suggest different sources of virus. (2 marks)`, scheme: [{ point: `(a) Symptoms appear first near the margin (columns 1–3: ${f1(bA(2)[0])} % in week 2, ${f1(bA(4)[0])} % by week 4) and spread across the field, reaching columns 10–12 last (${f1(bA(6)[3])} % in week 6)`, marks: 1 }, { point: `(b) ${f1(ringB(6)[0].pct)} ÷ ${f1(ringB(6)[2].pct)} = ${(+f1(ringB(6)[0].pct) / +f1(ringB(6)[2].pct)).toPrecision(2)} times`, marks: 1 }, { point: "(c) Field A: source outside the field at the weedy margin; aphids carried virus in from infected weeds", marks: 1 }, { point: "(c) Field B: source inside the field (the first infected plant, e.g. an infected transplant); spread mostly to nearby plants with a few longer jumps (winged aphids)", marks: 1 }], model: `(a) In Field A symptoms appear first in the columns nearest the weedy margin (${f1(bA(2)[0])} % of columns 1–3 by week 2) and then move across the field, reaching the far side last. (b) ${f1(ringB(6)[0].pct)} ÷ ${f1(ringB(6)[2].pct)} = ${(+f1(ringB(6)[0].pct) / +f1(ringB(6)[2].pct)).toPrecision(2)} times. (c) The gradient in Field A suggests aphids carried the virus in from infected weeds at the margin. In Field B the spread is centred on one plant inside the field, so that plant was the source; most new infections were close by, with a few further away where winged aphids flew.`, commonErrors: "Calculating a difference instead of a ratio; describing without using figures." },
      { id: `q-${R}-s1`, ref: R, stmts: S(3), type: "short", marks: 3, stem: "Explain why the transmission of plant viruses usually involves vectors such as aphids. (3 marks)", scheme: [{ point: "Plants are immobile / cannot move to (or touch) other plants", marks: 1 }, { point: "A virus cannot cross the intact cuticle / cell wall by itself; it needs a wound to enter a living cell", marks: 1 }, { point: "The vector (aphid) picks up the virus from an infected plant, carries it to a healthy plant and pierces its cells (with its stylets), putting the virus inside", marks: 1 }], model: "Plants are immobile, so an infected plant cannot pass the virus to a healthy one by moving. A virus particle cannot get through the cuticle and cell wall of an intact plant. An aphid picks up the virus when it feeds on an infected plant, moves to a healthy plant, and its stylets pierce the cells, putting the virus inside them.", commonErrors: "Only saying 'plants cannot move'; saying viruses are blown by the wind." },
      { id: `q-${R}-s2`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: "A virus causes stunting, leaf distortion and blotchy fruit in a tomato crop. Explain how these symptoms lead to losses in both crop production and quality of produce. (3 marks)", scheme: [{ point: "Stunting: smaller plants with less leaf area produce fewer / smaller fruit (lower yield)", marks: 1 }, { point: "Distorted leaves have less effective surface for light absorption, so less photosynthesis and growth (lower yield)", marks: 1 }, { point: "Blotchy fruit are of lower quality / less marketable / sell for a lower price", marks: 1 }], model: "Stunted plants are smaller, with less leaf area, so they produce fewer or smaller fruit. Distorted leaves absorb light less effectively, so the plant photosynthesises and grows less. Both reduce yield. Fruit with blotches are of lower quality and may be unsaleable even if their mass is normal.", commonErrors: "Mentioning only yield; forgetting that quality is a separate loss." },
      { id: `q-${R}-s3`, ref: R, stmts: S(2), type: "short", marks: 2, stem: "Suppose one virus causes severe symptoms in one crop but only mild symptoms in another. Give two reasons why infected plants can show different symptoms. (2 marks)", scheme: [{ point: "The kind of plant / species or variety differs in its response to the virus", marks: 1 }, { point: "The age of the plant when infected / growing conditions (temperature, light) / infection with more than one virus / strain of virus", marks: 1 }], model: "Different kinds of plant (and different varieties) respond differently to the same virus, and the symptoms also depend on how old the plant was when infected, the growing conditions, the strain of virus and whether other viruses are present.", commonErrors: "Saying the symptoms depend only on the aphid." },
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(1, 2, 3), type: "extended", marks: 6, stem: "Extended response. Plant viruses are a serious problem for vegetable growers in hot countries. Explain why plant viruses are important, describe the symptoms they can cause, and explain why their spread depends on vectors. Use an example of how understanding the vector can help control a disease. (6 marks)", scheme: [{ point: "Viruses cause many important plant diseases / affect crops worldwide", marks: 1 }, { point: "Losses in yield (e.g. less photosynthesis, stunting, fewer fruit) and in quality (blemished, misshapen produce)", marks: 1 }, { point: "Symptoms depend on the disease: yellowing, leaf distortion, mosaics, abnormalities of other parts such as stunting or abnormal fruit", marks: 1 }, { point: "Plants are immobile, and the virus cannot cross intact cell walls unaided", marks: 1 }, { point: "Vectors such as aphids pick up virus from infected plants, move (winged forms fly) and put virus into cells of healthy plants; not all viruses are aphid-borne", marks: 1 }, { point: "Control linked to the vector, e.g. removing infected weeds near the crop, reflective mulch / row covers keep aphids off, insecticides fail for non-persistent viruses, resistant varieties", marks: 1 }], levels: "Level 3 (5–6): importance (yield and quality), a range of symptoms, a clear explanation of why vectors are needed and a correctly reasoned control example. Level 2 (3–4): most points with some explanation; control mentioned but not fully linked to the vector. Level 1 (1–2): simple statements, for example that viruses damage crops and aphids spread them.", model: "Many important plant diseases are caused by viruses, which cause losses in all parts of the world. Infected plants may be stunted and their yellowed or distorted leaves photosynthesise less, so yields of fruit or grain fall; fruit may be blotchy or misshapen, reducing quality and price. Symptoms depend on the disease: yellowing of leaves, leaf distortion, mosaics and abnormalities of other parts such as fruit. Plants cannot move, and virus particles cannot cross intact cell walls, so viruses are usually carried by vectors. An aphid picks up virus while probing or feeding on an infected plant, moves to another plant (winged females fly between plants and fields) and its stylets put the virus into the new plant's cells. Not every virus is aphid-borne: whiteflies, thrips, nematodes and seed spread others. Knowing the vector guides control: for a non-persistent aphid-borne virus, insecticides act too slowly, so growers remove infected weeds around the field, use reflective mulch or row covers to keep aphids off young plants, or grow resistant varieties.", commonErrors: "Describing only symptoms; claiming all viruses are aphid-borne; recommending antibiotics." },
    ],
  };
})();
